function mvpalab_cleansfdata(cfg)
%% MVPALAB_CLEANSFDATA
%
%  This function removes the filtered data generated by a previous sliding
%  filter analysis, in order to prevent errors if the user repeats the
%  analysis with less frequency steps.
%
%  cfg.sf.filesLocation can be any folder selected by the user, so only
%  the files generated by the toolbox are removed: the feature vectors
%  (fv/s_*/ffv_*.mat) and the filtered data (data/s_*/fdata_*.mat). The
%  folders are removed only if they become empty.
%
%%  INPUT:
%
%  - {struct} - cfg:
%    Configuration structure (cfg.sf.filesLocation).

generated = {'fv','ffv_*.mat';'data','fdata_*.mat'};

for i = 1 : size(generated,1)
    folder = [cfg.sf.filesLocation filesep generated{i,1}];

    files = dir([folder filesep 's_*' filesep generated{i,2}]);
    for file = 1 : length(files)
        delete([files(file).folder filesep files(file).name]);
    end

    % rmdir fails without the 's' option if the folder is not empty:
    subjects = dir([folder filesep 's_*']);
    for sub = 1 : length(subjects)
        [~,~] = rmdir([subjects(sub).folder filesep subjects(sub).name]);
    end
    [~,~] = rmdir(folder);
end

end
